import heapq

def cheapest(graph, src, dst):
    dist = {src: 0}
    h = [(0, src)]
    while h:
        d, node = heapq.heappop(h)
        if node == dst:
            return d
        if d > dist.get(node, d):
            continue
        for nxt, w in graph.get(node, []):
            nd = d + w
            if nd < dist.get(nxt, float('inf')):
                dist[nxt] = nd
                heapq.heappush(h, (nd, nxt))
    return None

