    nodes = set(graph) | {m for ns in graph.values() for m in ns}
    indeg = {n: 0 for n in nodes}
    for ns in graph.values():
        for m in ns:
            indeg[m] += 1
    ready = [n for n in nodes if indeg[n] == 0]
    seen = 0
    while ready:
        n = ready.pop()
        seen += 1
        for m in graph.get(n, []):
            indeg[m] -= 1
            if indeg[m] == 0:
                ready.append(m)
    return seen < len(nodes)
